setup.command:
mcp-guard keys init && cat ~/.config/mcp-guard/keys/keys.json; echo "---KEYS DONE---"
cat > pp.config.yaml << 'EOF'
default_action: allow
rules: []
EOF
cat pp.config.yaml
cat > dummy-server.js << 'EOF'
const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout, terminal: false });
rl.on('line', (line) => {
  if (!line.trim()) return;
  let msg;
  try { msg = JSON.parse(line); } catch { return; }
  if (msg.method === 'initialize' && msg.id !== undefined) {
    const resp = { jsonrpc: '2.0', id: msg.id, result: { protocolVersion: '2025-11-25', capabilities: { tools: {} }, serverInfo: { name: 'dummy', version: '1.0.0' } } };
    console.log(JSON.stringify(resp));
  } else if (msg.method === 'tools/list' && msg.id !== undefined) {
    const resp = { jsonrpc: '2.0', id: msg.id, result: { tools: [{ name: 'hello', description: 'Say hello', inputSchema: { type: 'object', properties: {} } }] } };
    console.log(JSON.stringify(resp));
  } else if (msg.method === 'tools/call' && msg.id !== undefined) {
    const resp = { jsonrpc: '2.0', id: msg.id, result: { content: [{ type: 'text', text: 'hello world' }] } };
    console.log(JSON.stringify(resp));
  } else if (msg.method === 'ping' && msg.id !== undefined) {
    console.log(JSON.stringify({ jsonrpc: '2.0', id: msg.id, result: {} }));
  } else if (msg.id !== undefined && msg.method && msg.method.startsWith('notifications/')) {
    // notification, no reply
  } else if (msg.id !== undefined) {
    // generic: if has method, reply empty or handle resources/prompts lists
    if (msg.method === 'resources/list' || msg.method === 'prompts/list' || msg.method === 'resources/templates/list') {
      const key = msg.method === 'resources/list' ? 'resources' : msg.method === 'prompts/list' ? 'prompts' : 'resourceTemplates';
      console.log(JSON.stringify({ jsonrpc: '2.0', id: msg.id, result: { [key]: [] } }));
    } else if (msg.method === 'logging/setLevel' || msg.method === 'completion/complete') {
      console.log(JSON.stringify({ jsonrpc: '2.0', id: msg.id, result: {} }));
    } else {
      console.log(JSON.stringify({ jsonrpc: '2.0', id: msg.id, result: {} }));
    }
  }
});
EOF
cat dummy-server.js

